36	const FIRST_INSURANCE_PERCENT = 10;
37	
38	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
39	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
40	// intermediates to stay exact, so every percentage goes through here.
41	const percentOf = (amount: number, percent: number): number =>
42	  (amount * percent) / 100;
43	
44	// Rounding always favours MHPCO: premiums round up, payouts round down.
45	const roundPremium = (amount: number): number => Math.ceil(amount);
46	
47	const quoteStep = (step: Step): QuoteResult => {
48	  const basePremium = step.items.reduce(
49	    (sum, item) => sum + BASE_PREMIUMS[item.type],
50	    0,
51	  );
52	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
53	
54	  return {
55	    premium: roundPremium(
56	      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
57	    ),
58	  };
59	};
60	
61	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
62	  results: scenario.steps.map(quoteStep),
63	});
